  /* ---------- questions: o = options, c = correct option, w = one-line reason ---------- */
  var QA = [
    { en: ['What is the maximum deduction under Section 80C?', ['₹1,50,000', '₹50,000', '₹5,00,000'], 'ELSS, PPF, EPF, life insurance premium and more share one ₹1.5 lakh limit (old tax regime).'],
      ta: ['பிரிவு 80C-இன் அதிகபட்சக் கழிவு எவ்வளவு?', ['₹1,50,000', '₹50,000', '₹5,00,000'], 'ELSS, PPF, EPF, ஆயுள் காப்பீட்டு பிரீமியம் போன்றவை ஒரே ₹1.5 லட்ச வரம்பைப் பகிர்கின்றன (பழைய வரி முறை).'], c: 0 },
    { en: ['Section 80D gives a tax deduction for…', ['Health insurance premium', 'Home loan interest', 'Gold purchase'], 'You can deduct health insurance premiums for yourself, family and parents (old tax regime).'],
      ta: ['பிரிவு 80D எதற்கு வரிக் கழிவு தருகிறது?', ['மருத்துவக் காப்பீட்டு பிரீமியம்', 'வீட்டுக் கடன் வட்டி', 'தங்கம் வாங்குதல்'], 'உங்களுக்கும் குடும்பத்துக்கும் பெற்றோருக்குமான மருத்துவக் காப்பீட்டு பிரீமியத்தைக் கழிக்கலாம் (பழைய வரி முறை).'], c: 0 },
    { en: ['How much extra deduction does NPS get under 80CCD(1B)?', ['₹50,000', '₹10,000', '₹2,00,000'], 'This is over and above the ₹1.5 lakh of Section 80C.'],
      ta: ['80CCD(1B)-இல் NPS-க்கு கூடுதல் கழிவு எவ்வளவு?', ['₹50,000', '₹10,000', '₹2,00,000'], 'இது பிரிவு 80C-இன் ₹1.5 லட்சத்துக்கு மேல் கூடுதலாகக் கிடைக்கும்.'], c: 0 },
    { en: ['Which gives the biggest life cover for the lowest premium?', ['Term insurance', 'Endowment plan', 'Money-back plan'], 'Term plans are pure protection; endowment plans mix insurance with low-return savings.'],
      ta: ['குறைந்த பிரீமியத்தில் அதிக ஆயுள் பாதுகாப்பு எது தரும்?', ['டேர்ம் காப்பீடு', 'எண்டோவ்மென்ட் திட்டம்', 'மணி-பேக் திட்டம்'], 'டேர்ம் திட்டம் தூய பாதுகாப்பு; எண்டோவ்மென்ட் காப்பீட்டுடன் குறைந்த வருமானச் சேமிப்பைக் கலக்கிறது.'], c: 0 },
    { en: ['When does a term insurance plan pay?', ['Only if the person dies during the term', 'At the end of the term', 'Every 5 years'], 'There is no maturity amount – that is why the premium is low.'],
      ta: ['டேர்ம் காப்பீடு எப்போது பணம் தரும்?', ['காலத்துக்குள் மரணம் நிகழ்ந்தால் மட்டும்', 'காலம் முடிந்ததும்', 'ஒவ்வொரு 5 ஆண்டுக்கும்'], 'முதிர்வுத் தொகை இல்லை – அதனால்தான் பிரீமியம் குறைவு.'], c: 0 },
    { en: ['How big should an emergency fund be?', ['3 to 6 months of expenses', '1 week of salary', '5 years of salary'], 'It covers job loss or a hospital bill without breaking investments or borrowing.'],
      ta: ['அவசர நிதி எவ்வளவு இருக்க வேண்டும்?', ['3 முதல் 6 மாதச் செலவு', '1 வாரச் சம்பளம்', '5 ஆண்டுச் சம்பளம்'], 'வேலை இழப்பு அல்லது மருத்துவச் செலவை முதலீட்டை உடைக்காமல், கடன் வாங்காமல் சமாளிக்கலாம்.'], c: 0 },
    { en: ['What is the range of a CIBIL score?', ['300 to 900', '0 to 100', '1 to 10'], '750 and above is usually seen as good.'],
      ta: ['CIBIL மதிப்பெண்ணின் வரம்பு என்ன?', ['300 முதல் 900', '0 முதல் 100', '1 முதல் 10'], 'பொதுவாக 750 மற்றும் அதற்கு மேல் நல்லதாகக் கருதப்படுகிறது.'], c: 0 },
    { en: ['Which of these lowers your CIBIL score?', ['Paying EMIs late', 'Paying the full card bill', 'Having a savings account'], 'Late or missed payments stay on your credit report for years.'],
      ta: ['இவற்றில் எது CIBIL மதிப்பெண்ணைக் குறைக்கும்?', ['EMI-யைத் தாமதமாகச் செலுத்துதல்', 'கார்டு பில் முழுவதும் செலுத்துதல்', 'சேமிப்புக் கணக்கு வைத்திருத்தல்'], 'தாமதமான அல்லது தவறிய செலுத்துதல்கள் பல ஆண்டுகள் கடன் அறிக்கையில் இருக்கும்.'], c: 0 },
    { en: ['EMI stands for…', ['Equated Monthly Instalment', 'Extra Money Income', 'Easy Monthly Interest'], 'Each EMI pays part interest and part of the loan amount.'],
      ta: ['EMI என்பதன் விரிவு…', ['Equated Monthly Instalment (சம மாதத் தவணை)', 'Extra Money Income', 'Easy Monthly Interest'], 'ஒவ்வொரு EMI-யிலும் ஒரு பகுதி வட்டி, ஒரு பகுதி கடன் தொகை.'], c: 0 },
    { en: ['A longer loan tenure means…', ['Lower EMI but more total interest', 'Lower EMI and less interest', 'Higher EMI and less interest'], 'Stretching a loan makes it look cheaper each month but costs more overall.'],
      ta: ['கடன் காலம் நீண்டால்…', ['EMI குறையும், ஆனால் மொத்த வட்டி கூடும்', 'EMI-யும் வட்டியும் குறையும்', 'EMI கூடும், வட்டி குறையும்'], 'மாதந்தோறும் மலிவாகத் தெரியும், ஆனால் மொத்தச் செலவு அதிகம்.'], c: 0 },
    { en: ['With 6% inflation, something that costs ₹100 today will cost about…', ['₹106 next year', '₹94 next year', '₹100 next year'], 'Prices rising means money kept idle buys less every year.'],
      ta: ['6% பணவீக்கத்தில் இன்று ₹100 விலையுள்ள பொருள் அடுத்த ஆண்டு சுமார்…', ['₹106', '₹94', '₹100'], 'விலைகள் உயர்வதால் சும்மா வைத்த பணம் ஆண்டுதோறும் குறைவாகவே வாங்கும்.'], c: 0 },
    { en: ['Money earns 3% in a savings account while inflation is 6%. What happens?', ['It loses buying power', 'It doubles quickly', 'Nothing changes'], 'Your real return is about 3% − 6% = −3% a year.'],
      ta: ['சேமிப்புக் கணக்கில் 3% வட்டி, பணவீக்கம் 6%. என்ன நடக்கும்?', ['வாங்கும் சக்தி குறையும்', 'வேகமாக இரட்டிப்பாகும்', 'ஒன்றும் மாறாது'], 'உண்மையான வருமானம் சுமார் 3% − 6% = −3% ஆண்டுக்கு.'], c: 0 },
    { en: ['What is a big benefit of a SIP?', ['Rupee cost averaging and discipline', 'Guaranteed returns', 'No market risk'], 'You buy more units when prices are low and fewer when high, without timing the market.'],
      ta: ['SIP-இன் பெரிய பலன் என்ன?', ['சராசரிச் செலவு மற்றும் ஒழுக்கம்', 'உறுதியான வருமானம்', 'சந்தை அபாயம் இல்லை'], 'விலை குறையும்போது அதிக யூனிட்கள், அதிகமாகும்போது குறைவு – சந்தையை கணிக்கத் தேவையில்லை.'], c: 0 },
    { en: ['SIP or lump sum when markets go up and down a lot?', ['SIP reduces timing risk', 'Lump sum is always safer', 'Both are guaranteed'], 'A lump sum can do well, but investing all at a peak hurts. SIP spreads the risk.'],
      ta: ['சந்தை அதிகம் ஏறி இறங்கும்போது SIP-ஆ மொத்தத் தொகையா?', ['SIP நேர அபாயத்தைக் குறைக்கும்', 'மொத்தத் தொகை எப்போதும் பாதுகாப்பு', 'இரண்டும் உறுதியானவை'], 'உச்சத்தில் மொத்தமாகப் போட்டால் நஷ்டம் வரலாம். SIP அபாயத்தைப் பரப்புகிறது.'], c: 0 },
    { en: ['What is the lock-in period of an ELSS fund?', ['3 years', '15 years', 'No lock-in'], 'ELSS has the shortest lock-in among 80C options.'],
      ta: ['ELSS ஃபண்டின் லாக்-இன் காலம் என்ன?', ['3 ஆண்டுகள்', '15 ஆண்டுகள்', 'லாக்-இன் இல்லை'], '80C வாய்ப்புகளில் ELSS-க்குத்தான் மிகக் குறைந்த லாக்-இன்.'], c: 0 },
    { en: ['How long is a PPF account locked in?', ['15 years', '3 years', '1 year'], 'Partial withdrawals are allowed after some years; it can be extended in 5-year blocks.'],
      ta: ['PPF கணக்கு எத்தனை ஆண்டுகள் பூட்டப்பட்டிருக்கும்?', ['15 ஆண்டுகள்', '3 ஆண்டுகள்', '1 ஆண்டு'], 'சில ஆண்டுகளுக்குப் பின் பகுதியளவு எடுக்கலாம்; 5 ஆண்டு தொகுதிகளாக நீட்டிக்கலாம்.'], c: 0 },
    { en: ['Who backs the PPF scheme?', ['The Government of India', 'A private bank', 'A stock exchange'], 'That makes PPF one of the safest long-term options.'],
      ta: ['PPF திட்டத்துக்கு யார் உத்தரவாதம்?', ['இந்திய அரசு', 'ஒரு தனியார் வங்கி', 'ஒரு பங்குச் சந்தை'], 'அதனால் PPF மிகப் பாதுகாப்பான நீண்டகாலத் திட்டங்களில் ஒன்று.'], c: 0 },
    { en: ['When you exit NPS at 60, at least how much must buy an annuity (pension)?', ['40% of the corpus', '100% of the corpus', 'Nothing'], 'Up to 60% can be taken as a lump sum; the rest gives a monthly pension.'],
      ta: ['60 வயதில் NPS-இலிருந்து வெளியேறும்போது குறைந்தது எவ்வளவு ஓய்வூதியத்துக்குப் போக வேண்டும்?', ['தொகுப்பில் 40%', 'தொகுப்பில் 100%', 'எதுவும் இல்லை'], '60% வரை மொத்தமாக எடுக்கலாம்; மீதி மாத ஓய்வூதியம் தரும்.'], c: 0 },
    { en: ['Do you need your UPI PIN to receive money?', ['No, only to pay', 'Yes, always', 'Only for big amounts'], 'Anyone asking for your PIN "to send you money" is a fraudster.'],
      ta: ['பணம் பெற UPI PIN தேவையா?', ['இல்லை, அனுப்ப மட்டுமே', 'ஆம், எப்போதும்', 'பெரிய தொகைக்கு மட்டும்'], '"பணம் அனுப்ப" PIN கேட்பவர் மோசடிக்காரர்.'], c: 0 },
    { en: ['Which number do you call to report cyber fraud in India?', ['1930', '100', '108'], 'You can also report at cybercrime.gov.in. Call quickly to help block the money.'],
      ta: ['இந்தியாவில் சைபர் மோசடியைப் புகார் செய்ய எந்த எண்ணை அழைப்பது?', ['1930', '100', '108'], 'cybercrime.gov.in-இலும் புகார் செய்யலாம். பணத்தைத் தடுக்க விரைவாக அழையுங்கள்.'], c: 0 },
    { en: ['If you pay only the minimum due on a credit card…', ['Interest is charged on the rest', 'There is no interest', 'The bank forgives the rest'], 'Card interest is about 3–3.5% a month, roughly 36–42% a year.'],
      ta: ['கிரெடிட் கார்டில் குறைந்தபட்சத் தொகை மட்டும் செலுத்தினால்…', ['மீதிக்கு வட்டி விதிக்கப்படும்', 'வட்டி இல்லை', 'மீதியை வங்கி தள்ளுபடி செய்யும்'], 'கார்டு வட்டி மாதம் சுமார் 3–3.5%, ஆண்டுக்கு சுமார் 36–42%.'], c: 0 },
    { en: ['A good rule for total EMIs is to keep them below…', ['About 40% of your income', '90% of your income', 'Exactly 50% of savings'], 'Higher EMIs leave too little for needs and savings.'],
      ta: ['மொத்த EMI-கள் எவ்வளவுக்குக் கீழ் இருப்பது நல்லது?', ['வருமானத்தில் சுமார் 40%', 'வருமானத்தில் 90%', 'சேமிப்பில் சரியாக 50%'], 'அதிக EMI தேவைகளுக்கும் சேமிப்புக்கும் குறைவாகவே விடும்.'], c: 0 },
    { en: ['What does a health insurance "cashless" claim mean?', ['The insurer pays the network hospital directly', 'You get cash back every year', 'Treatment is free everywhere'], 'At a network hospital you don\'t pay the covered bill yourself.'],
      ta: ['மருத்துவக் காப்பீட்டில் "கேஷ்லெஸ்" என்றால்?', ['காப்பீட்டு நிறுவனம் நெட்வொர்க் மருத்துவமனைக்கு நேரடியாகச் செலுத்தும்', 'ஆண்டுதோறும் பணம் திரும்பக் கிடைக்கும்', 'எல்லா இடங்களிலும் இலவச சிகிச்சை'], 'நெட்வொர்க் மருத்துவமனையில் காப்பீட்டுக்குட்பட்ட பில்லை நீங்கள் செலுத்த வேண்டியதில்லை.'], c: 0 },
    { en: ['Who regulates mutual funds in India?', ['SEBI', 'IRDAI', 'TRAI'], 'SEBI regulates mutual funds and the stock market; IRDAI regulates insurance.'],
      ta: ['இந்தியாவில் மியூச்சுவல் ஃபண்டுகளை யார் ஒழுங்குபடுத்துகிறார்கள்?', ['SEBI', 'IRDAI', 'TRAI'], 'SEBI மியூச்சுவல் ஃபண்டுகளையும் பங்குச் சந்தையையும் ஒழுங்குபடுத்துகிறது; IRDAI காப்பீட்டை.'], c: 0 },
    { en: ['Using the Rule of 72, money growing at 12% a year doubles in about…', ['6 years', '12 years', '72 years'], '72 ÷ 12 = 6. The higher the return, the faster it doubles.'],
      ta: ['72 விதிப்படி, ஆண்டுக்கு 12% வளரும் பணம் சுமார் எத்தனை ஆண்டுகளில் இரட்டிப்பாகும்?', ['6 ஆண்டுகள்', '12 ஆண்டுகள்', '72 ஆண்டுகள்'], '72 ÷ 12 = 6. வருமானம் அதிகமானால் வேகமாக இரட்டிப்பாகும்.'], c: 0 },
    { en: ['Diversification means…', ['Spreading money across different investments', 'Putting everything in one share', 'Keeping all money as cash'], 'When one investment falls, others can hold up.'],
      ta: ['பன்முகப்படுத்தல் என்றால்…', ['பணத்தைப் பல்வேறு முதலீடுகளில் பிரித்தல்', 'எல்லாவற்றையும் ஒரே பங்கில் போடுதல்', 'எல்லாப் பணத்தையும் கையிருப்பாக வைத்தல்'], 'ஒன்று சரிந்தாலும் மற்றவை தாங்கும்.'], c: 0 },
    { en: ['Bank deposits are insured by DICGC up to how much per depositor per bank?', ['₹5 lakh', '₹50,000', 'Unlimited'], 'This covers savings, FD and other deposits together, including interest.'],
      ta: ['ஒரு வங்கியில் ஒரு வைப்பாளருக்கு DICGC காப்பீடு எவ்வளவு வரை?', ['₹5 லட்சம்', '₹50,000', 'வரம்பில்லை'], 'சேமிப்பு, FD மற்றும் பிற வைப்புகள் வட்டியுடன் சேர்த்து இதில் அடங்கும்.'], c: 0 },
    { en: ['Before taking advice from an investment adviser, check that they are…', ['SEBI-registered', 'Famous on social media', 'Promising high returns'], 'Registered advisers must follow rules and can be held responsible.'],
      ta: ['முதலீட்டு ஆலோசகரிடம் ஆலோசனை பெறும் முன் சரிபார்க்க வேண்டியது…', ['SEBI-யில் பதிவு பெற்றவரா', 'சமூக ஊடகத்தில் பிரபலமா', 'அதிக லாபம் தருவதாகச் சொல்கிறாரா'], 'பதிவுபெற்ற ஆலோசகர்கள் விதிகளைப் பின்பற்ற வேண்டும்; பொறுப்பேற்க வேண்டும்.'], c: 0 },
    { en: ['The NAV of a mutual fund is…', ['The price of one unit', 'The fund\'s yearly fee', 'The guaranteed return'], 'NAV changes every day with the value of the fund\'s investments.'],
      ta: ['மியூச்சுவல் ஃபண்டின் NAV என்பது…', ['ஒரு யூனிட்டின் விலை', 'ஃபண்டின் ஆண்டுக் கட்டணம்', 'உறுதியான வருமானம்'], 'ஃபண்டின் முதலீடுகளின் மதிப்புடன் NAV தினமும் மாறும்.'], c: 0 },
    { en: ['A mutual fund\'s expense ratio is…', ['Its yearly fee as a % of your money', 'The tax on gains', 'The entry price'], 'A lower expense ratio leaves more of the return for you.'],
      ta: ['மியூச்சுவல் ஃபண்டின் செலவு விகிதம் (expense ratio) என்பது…', ['உங்கள் பணத்தின் % ஆக ஆண்டுக் கட்டணம்', 'லாபத்தின் மீதான வரி', 'நுழைவு விலை'], 'செலவு விகிதம் குறைவாக இருந்தால் வருமானத்தில் அதிகம் உங்களுக்குக் கிடைக்கும்.'], c: 0 },
    { en: ['Where is a good place to park an emergency fund?', ['Savings account or liquid fund', 'Small-company shares', 'Crypto'], 'It must be safe and quick to withdraw.'],
      ta: ['அவசர நிதியை எங்கே வைப்பது நல்லது?', ['சேமிப்புக் கணக்கு அல்லது லிக்விட் ஃபண்ட்', 'சிறு நிறுவனப் பங்குகள்', 'கிரிப்டோ'], 'அது பாதுகாப்பாகவும் உடனே எடுக்கக்கூடியதாகவும் இருக்க வேண்டும்.'], c: 0 },
    { en: ['Health insurance is important because…', ['One hospital stay can wipe out years of savings', 'It gives high returns', 'It is a tax-free investment'], 'Buy enough cover early, when premiums are lower.'],
      ta: ['மருத்துவக் காப்பீடு ஏன் முக்கியம்?', ['ஒரு மருத்துவமனை வாசம் பல ஆண்டுச் சேமிப்பை அழிக்கலாம்', 'அதிக வருமானம் தரும்', 'வரியில்லா முதலீடு'], 'பிரீமியம் குறைவாக இருக்கும் இளம் வயதிலேயே போதுமான காப்பீடு வாங்குங்கள்.'], c: 0 },
    { en: ['Which grows faster over many years, usually?', ['Equity mutual funds', 'Cash at home', 'A savings account'], 'Equity can beat inflation over the long term, though it goes up and down on the way.'],
      ta: ['பல ஆண்டுகளில் பொதுவாக எது வேகமாக வளரும்?', ['ஈக்விட்டி மியூச்சுவல் ஃபண்டுகள்', 'வீட்டில் வைத்த பணம்', 'சேமிப்புக் கணக்கு'], 'நீண்டகாலத்தில் ஈக்விட்டி பணவீக்கத்தைத் தாண்டலாம், ஆனால் வழியில் ஏறி இறங்கும்.'], c: 0 }
  ];
  var QK = [
    { en: ['Which is a NEED?', ['School books', 'A new toy', 'Extra chocolates'], 'Needs are things we must have; wants are nice to have.'], ta: ['இவற்றில் எது தேவை?', ['பள்ளிப் புத்தகங்கள்', 'புதிய பொம்மை', 'கூடுதல் சாக்லேட்'], 'தேவை என்பது கட்டாயம் வேண்டியது; விருப்பம் இருந்தால் நல்லது.'], c: 0 },
    { en: ['What does a piggy bank help you do?', ['Save money', 'Spend faster', 'Lose coins'], 'A little saved every day becomes a lot.'], ta: ['உண்டியல் எதற்கு உதவும்?', ['பணம் சேமிக்க', 'வேகமாகச் செலவிட', 'நாணயங்களை இழக்க'], 'தினமும் கொஞ்சம் சேமித்தால் அதிகமாகும்.'], c: 0 },
    { en: ['The extra money a bank pays you for keeping money there is called…', ['Interest', 'Tax', 'Fine'], 'Banks pay interest because they lend your money to others.'], ta: ['வங்கியில் பணம் வைத்தால் வங்கி தரும் கூடுதல் பணம்…', ['வட்டி', 'வரி', 'அபராதம்'], 'உங்கள் பணத்தை மற்றவர்களுக்குக் கடன் தருவதால் வங்கி வட்டி தருகிறது.'], c: 0 },
    { en: ['Someone on the phone asks for the OTP sent to Mom\'s phone. You should…', ['Never tell, and tell a parent', 'Tell them quickly', 'Post it online'], 'OTPs are secret keys. Never share them with anyone.'], ta: ['போனில் ஒருவர் அம்மாவின் போனுக்கு வந்த OTP-ஐக் கேட்கிறார். நீங்கள்…', ['சொல்லக் கூடாது, பெற்றோரிடம் சொல்ல வேண்டும்', 'உடனே சொல்ல வேண்டும்', 'இணையத்தில் போட வேண்டும்'], 'OTP ஒரு ரகசியச் சாவி. யாரிடமும் சொல்லக் கூடாது.'], c: 0 },
    { en: ['When you get pocket money, it is smart to…', ['Save a part first', 'Spend it all today', 'Hide it and forget'], 'Pay yourself first, then spend what is left.'], ta: ['கைச்செலவுப் பணம் கிடைத்தால் புத்திசாலித்தனம்…', ['முதலில் ஒரு பகுதியைச் சேமிப்பது', 'இன்றே எல்லாவற்றையும் செலவிடுவது', 'ஒளித்து வைத்து மறப்பது'], 'முதலில் சேமியுங்கள், மீதியைச் செலவிடுங்கள்.'], c: 0 },
    { en: ['If you save ₹100 every month for 12 months, you have…', ['₹1,200', '₹120', '₹100'], '100 × 12 = 1,200. Small amounts add up.'], ta: ['12 மாதம் மாதம் ₹100 சேமித்தால்…', ['₹1,200', '₹120', '₹100'], '100 × 12 = 1,200. சிறு தொகைகள் சேர்ந்து பெரிதாகும்.'], c: 0 },
    { en: ['A budget is…', ['A plan for how to use money', 'A kind of bank', 'A type of coin'], 'A budget tells your money where to go.'], ta: ['பட்ஜெட் என்பது…', ['பணத்தை எப்படிப் பயன்படுத்துவது என்ற திட்டம்', 'ஒரு வகை வங்கி', 'ஒரு வகை நாணயம்'], 'பட்ஜெட் உங்கள் பணம் எங்கே போக வேண்டும் எனச் சொல்லும்.'], c: 0 },
    { en: ['Before buying something, it is good to…', ['Compare prices and think', 'Buy the first one you see', 'Borrow money for it'], 'Waiting a day often saves money.'], ta: ['ஒன்றை வாங்கும் முன்…', ['விலைகளை ஒப்பிட்டு யோசிப்பது நல்லது', 'முதலில் பார்த்ததை வாங்குவது', 'அதற்குக் கடன் வாங்குவது'], 'ஒரு நாள் காத்திருந்தால் பெரும்பாலும் பணம் மிச்சமாகும்.'], c: 0 },
    { en: ['Gold, fixed deposits and shares are kinds of…', ['Investments', 'Toys', 'Bills'], 'Investments can help money grow over time.'], ta: ['தங்கம், FD, பங்குகள் இவை…', ['முதலீடுகள்', 'பொம்மைகள்', 'பில்கள்'], 'முதலீடுகள் காலப்போக்கில் பணத்தை வளர்க்க உதவும்.'], c: 0 },
    { en: ['An ATM card PIN should be…', ['Kept secret', 'Written on the card', 'Told to friends'], 'Anyone with the PIN can take money out.'], ta: ['ATM கார்டின் PIN…', ['ரகசியமாக வைக்க வேண்டும்', 'கார்டிலேயே எழுத வேண்டும்', 'நண்பர்களிடம் சொல்ல வேண்டும்'], 'PIN தெரிந்தவர் யாரும் பணம் எடுக்கலாம்.'], c: 0 },
    { en: ['If you borrow ₹50 from a friend, you should…', ['Return it on time', 'Forget about it', 'Borrow more'], 'Returning on time builds trust – banks call it a good credit score.'], ta: ['நண்பரிடம் ₹50 கடன் வாங்கினால்…', ['சரியான நேரத்தில் திருப்பித் தர வேண்டும்', 'மறந்துவிட வேண்டும்', 'இன்னும் கடன் வாங்க வேண்டும்'], 'சரியான நேரத்தில் திருப்பித் தந்தால் நம்பிக்கை வளரும் – வங்கிகள் இதை நல்ல கடன் மதிப்பெண் என்கின்றன.'], c: 0 },
    { en: ['Things costing more every year is called…', ['Inflation', 'Saving', 'Interest'], 'That\'s why saving and investing early matters.'], ta: ['ஆண்டுதோறும் விலைகள் கூடுவதை…', ['பணவீக்கம்', 'சேமிப்பு', 'வட்டி'], 'அதனால்தான் சீக்கிரம் சேமிப்பதும் முதலீடு செய்வதும் முக்கியம்.'], c: 0 },
    { en: ['You want a ₹2,000 bicycle. The best plan is…', ['Save a little every week', 'Wait for a miracle', 'Spend on sweets first'], 'A goal plus a weekly saving plan gets you there.'], ta: ['₹2,000 சைக்கிள் வேண்டும். சிறந்த திட்டம்…', ['வாரம் தோறும் கொஞ்சம் சேமிப்பது', 'அதிசயத்துக்குக் காத்திருப்பது', 'முதலில் இனிப்புக்குச் செலவிடுவது'], 'இலக்கும் வாராந்திரச் சேமிப்புத் திட்டமும் உங்களை அங்கு சேர்க்கும்.'], c: 0 },
    { en: ['Insurance helps a family when…', ['Something bad happens, like a hospital visit', 'They go shopping', 'They win a game'], 'Insurance pays big bills so savings stay safe.'], ta: ['காப்பீடு குடும்பத்துக்கு எப்போது உதவும்?', ['மருத்துவமனை போன்ற கஷ்டம் வரும்போது', 'ஷாப்பிங் போகும்போது', 'ஆட்டத்தில் வெல்லும்போது'], 'பெரிய பில்களைக் காப்பீடு செலுத்துவதால் சேமிப்பு பாதுகாப்பாக இருக்கும்.'], c: 0 },
    { en: ['Who prints India\'s currency notes?', ['The Reserve Bank of India', 'Your school', 'A shop'], 'The RBI is India\'s central bank.'], ta: ['இந்திய ரூபாய் நோட்டுகளை யார் வெளியிடுகிறார்கள்?', ['இந்திய ரிசர்வ் வங்கி', 'உங்கள் பள்ளி', 'ஒரு கடை'], 'RBI இந்தியாவின் மத்திய வங்கி.'], c: 0 },
    { en: ['Which helps money grow over many years?', ['Investing', 'Keeping it under the bed', 'Losing it'], 'Invested money can earn more money – that is compounding.'], ta: ['பல ஆண்டுகளில் பணம் வளர எது உதவும்?', ['முதலீடு', 'கட்டிலுக்கு அடியில் வைப்பது', 'தொலைப்பது'], 'முதலீடு செய்த பணம் மேலும் பணம் ஈட்டும் – அதுவே கூட்டு வட்டி.'], c: 0 },
    { en: ['"Buy now, pay later" means…', ['You owe the money later', 'It is free', 'Someone else pays'], 'You still have to pay – sometimes with extra charges.'], ta: ['"இப்போது வாங்கு, பின்னர் செலுத்து" என்றால்…', ['பின்னர் அந்தப் பணத்தைச் செலுத்த வேண்டும்', 'இலவசம்', 'வேறு யாராவது செலுத்துவார்கள்'], 'நீங்கள் செலுத்தியே ஆக வேண்டும் – சில நேரம் கூடுதல் கட்டணத்துடன்.'], c: 0 },
    { en: ['Sharing a little money to help others is…', ['A kind thing to do', 'A waste', 'Against the rules'], 'Save, spend and share – all three are good habits.'], ta: ['மற்றவர்களுக்கு உதவக் கொஞ்சம் பணம் பகிர்வது…', ['நல்ல செயல்', 'வீண்', 'விதிமீறல்'], 'சேமி, செலவிடு, பகிர் – மூன்றுமே நல்ல பழக்கங்கள்.'], c: 0 },
    { en: ['What is the symbol of the Indian rupee?', ['₹', '$', '€'], 'The ₹ symbol has been used since 2010.'], ta: ['இந்திய ரூபாயின் குறியீடு எது?', ['₹', '$', '€'], '₹ குறியீடு 2010 முதல் பயன்பாட்டில் உள்ளது.'], c: 0 },
    { en: ['Earning pocket money by helping at home teaches that…', ['Money comes from work', 'Money grows on trees', 'Money is never needed'], 'People earn money by doing useful work.'], ta: ['வீட்டில் உதவி செய்து கைச்செலவுப் பணம் பெறுவது கற்றுத் தருவது…', ['பணம் உழைப்பால் வரும்', 'பணம் மரத்தில் காய்க்கும்', 'பணம் தேவையே இல்லை'], 'பயனுள்ள வேலை செய்வதால்தான் மக்கள் பணம் ஈட்டுகிறார்கள்.'], c: 0 }
  ];
